c.cpp:
class Solution {
public:
    int numberOfDays(int year, int month) {
        if (month == 12)
            return 31;
        std::tm a = {}, b = {};
        a.tm_year = year - 1900; a.tm_mon = month - 1; a.tm_mday = 1;
        b.tm_year = year - 1900; b.tm_mon = month;     b.tm_mday = 1;
        time_t ta = mktime(&a), tb = mktime(&b);
        return int(difftime(tb, ta) / 86400);
    }
};

